#!/usr/bin/env python3
import socket, sys, time

s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
s.connect("/tmp/qemu-monitor.sock")
s.settimeout(0.6)


def drain():
    o = b""
    try:
        while True:
            d = s.recv(4096)
            if not d:
                break
            o += d
    except Exception:
        pass
    return o.decode(errors="replace")


drain()
for cmd in sys.argv[1:]:
    s.sendall(cmd.encode() + b"\n")
    time.sleep(0.4)
    print(drain(), end="")

