#!/usr/bin/env python3
"""Send keystrokes to the VM through the QEMU monitor socket.

Usage:  sendkeys.py "text to type" [--keys key1 key2 ...]
Text is translated to QEMU 'sendkey' key names.
"""
import socket
import sys
import time

SOCK = "/tmp/qemu-monitor.sock"

SHIFTED = {
    "!": "1", "@": "2", "#": "3", "$": "4", "%": "5", "^": "6",
    "&": "7", "*": "8", "(": "9", ")": "0", "_": "minus", "+": "equal",
    "{": "bracket_left", "}": "bracket_right", ":": "semicolon",
    '"': "apostrophe", "|": "backslash", "<": "comma", ">": "dot",
    "?": "slash", "~": "grave_accent",
}
PLAIN = {
    " ": "spc", "-": "minus", "=": "equal", "[": "bracket_left",
    "]": "bracket_right", ";": "semicolon", "'": "apostrophe",
    "\\": "backslash", ",": "comma", ".": "dot", "/": "slash",
    "`": "grave_accent", "\n": "ret", "\t": "tab",
}


def keys_for(text):
    out = []
    for ch in text:
        if ch.isalpha():
            out.append(ch.lower() if ch.islower() else "shift-" + ch.lower())
        elif ch.isdigit():
            out.append(ch)
        elif ch in SHIFTED:
            out.append("shift-" + SHIFTED[ch])
        elif ch in PLAIN:
            out.append(PLAIN[ch])
        else:
            raise SystemExit("unmapped char %r" % ch)
    return out


def send(keys, delay=0.08):
    s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    s.connect(SOCK)
    s.settimeout(0.3)
    for k in keys:
        s.sendall(("sendkey " + k + "\n").encode())
        time.sleep(delay)
        try:
            while s.recv(65536):
                pass
        except Exception:
            pass
    s.close()


if __name__ == "__main__":
    args = sys.argv[1:]
    keys = []
    if args and args[0] != "--keys":
        keys += keys_for(args.pop(0))
    if args and args[0] == "--keys":
        keys += args[1:]
    send(keys)
    print("sent:", " ".join(keys))

